package com.ianblk.zianmobs;
import java.util.*;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.common.util.FakePlayerFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
final class CompanionFlightRefinementSmoke {
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 static void run(ServerPlayer original,Companions s){var level=original.serverLevel();var p=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(UUID.fromString("28b4cf9f-1b1f-42e9-8d55-74b34f8afc20"),"FlightRefine"));p.moveTo(original.getX(),original.getY(),original.getZ(),0,0);p.setHealth(p.getMaxHealth());boolean added=!level.players().contains(p);if(added)level.players().add(p);var blocks=new LinkedHashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();double x=p.getX(),y=p.getY(),z=p.getZ();try {
  s.grant(p.getUUID(),"cubee_fire",Long.MAX_VALUE);s.summon(p,"cubee_fire");var pet=s.activeEntity(p.getUUID());pet.moveTo(x-4,y+1,z);double maxLag=0;for(int n=0;n<100;n++){p.moveTo(p.getX()+.28,y,z);level.getChunk(p.blockPosition());var before=pet.position();pet.tick();check(s.activeEntity(p.getUUID())==pet,"Companion stored while running");check(pet.position().distanceTo(before)<1.5,"Catch-up used a teleport inside flight range");maxLag=Math.max(maxLag,pet.distanceTo(p));}check(maxLag<16&&pet.distanceTo(p)<7,"Flight cannot catch sprinting owner: max="+maxLag+" final="+pet.distanceTo(p));s.store(p.getUUID(),false);p.moveTo(x,y,z);
  var center=p.blockPosition();for(int dx=-5;dx<=5;dx++)for(int dz=-5;dz<=5;dz++)for(int dy=-1;dy<=1;dy++){var pos=center.offset(dx,dy,dz);blocks.put(pos,level.getBlockState(pos));level.setBlockAndUpdate(pos,Blocks.WATER.defaultBlockState());}s.summon(p,"cubee_fire");pet=s.activeEntity(p.getUUID());check(!level.containsAnyLiquid(pet.getBoundingBox())&&pet.getY()>=center.getY()+2,"Water summon did not seek free air above surface");for(int n=0;n<100;n++)pet.tick();check(s.activeEntity(p.getUUID())==pet&&!level.containsAnyLiquid(pet.getBoundingBox()),"Water follow stored or submerged companion");pet.moveTo(x+17,y+3,z);for(int n=0;n<20;n++){pet.tickCount++;s.tetherTick(pet,p);}check(s.activeEntity(p.getUUID())==pet&&pet.distanceToSqr(p)<=256&&!level.containsAnyLiquid(pet.getBoundingBox()),"Water recall failed");s.store(p.getUUID(),false);blocks.forEach((pos,state)->level.setBlockAndUpdate(pos,state));blocks.clear();
  // Failed recovery must neither move an entity into a wall nor store a living companion.
  s.summon(p,"cubee_fire");pet=s.activeEntity(p.getUUID());pet.moveTo(x+17,y+1,z);for(int dx=-5;dx<=5;dx++)for(int dz=-5;dz<=5;dz++)for(int dy=-1;dy<=16;dy++){var pos=center.offset(dx,dy,dz);blocks.put(pos,level.getBlockState(pos));level.setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());}var at=pet.position();check(!s.place(pet,p)&&pet.position().equals(at),"Failed placement moved pet into an invalid candidate");for(int n=0;n<40;n++){pet.tickCount++;s.tetherTick(pet,p);}check(s.activeEntity(p.getUUID())==pet&&pet.position().equals(at),"Missing air stored companion or moved it unsafely");pet.moveTo(x+33,y+1,z);s.tetherTick(pet,p);check(s.activeEntity(p.getUUID())==null,"32 block withdrawal changed");
 }finally{s.store(p.getUUID(),false);blocks.forEach((pos,state)->level.setBlockAndUpdate(pos,state));if(added)level.players().remove(p);}}
}
